import{_ as r,o as e,c as a,ak as o}from"./chunks/framework.CMX7UUIo.js";const g=JSON.parse('{"title":"小麦粉（面粉）","description":"","frontmatter":{"title":"小麦粉（面粉）"},"headers":[],"relativePath":"crops/wheat/wheat-flour.md","filePath":"crops/wheat/wheat-flour.md"}'),n={name:"crops/wheat/wheat-flour.md"};function l(d,t,i,s,m,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="小麦粉-面粉" tabindex="-1">小麦粉(面粉) <a class="header-anchor" href="#小麦粉-面粉" aria-label="Permalink to “小麦粉(面粉)”">​</a></h1><p>小麦粉(面粉)是由小麦经过碾磨制粉，部分或全部去除麸皮和胚，用于制作面制食品的产品。</p><h2 id="营养价值" tabindex="-1">营养价值 <a class="header-anchor" href="#营养价值" aria-label="Permalink to “营养价值”">​</a></h2><p>小麦粉中含有<a href="https://baike.baidu.com/item/%E8%9B%8B%E7%99%BD%E8%B4%A8/309120?fromModule=lemma_inlink" target="_blank" rel="noreferrer">蛋白质</a>、<a href="https://baike.baidu.com/item/%E6%B7%80%E7%B2%89/781685?fromModule=lemma_inlink" target="_blank" rel="noreferrer">淀粉</a>、<a href="https://baike.baidu.com/item/%E8%84%82%E8%82%AA/85926?fromModule=lemma_inlink" target="_blank" rel="noreferrer">脂肪</a>、<a href="https://baike.baidu.com/item/%E7%BB%B4%E7%94%9F%E7%B4%A0/161385?fromModule=lemma_inlink" target="_blank" rel="noreferrer">维生素</a>和无机盐等。小麦粉中的蛋白质含量比其他谷物产品高，一般在11%以上，高的可达15%--20%，由<a href="https://baike.baidu.com/item/%E9%BA%A6%E9%86%87%E6%BA%B6%E8%9B%8B%E7%99%BD/5601194?fromModule=lemma_inlink" target="_blank" rel="noreferrer">麦醇溶蛋白</a>和<a href="https://baike.baidu.com/item/%E9%BA%A6%E8%B0%B7%E8%9B%8B%E7%99%BD/5779960?fromModule=lemma_inlink" target="_blank" rel="noreferrer">麦谷蛋白</a>组成，它们吸水后可揉成具有粘弹性的面筋质，因此用小麦粉可制成独特品质和<a href="https://baike.baidu.com/item/%E9%A3%8E%E5%91%B3/133106?fromModule=lemma_inlink" target="_blank" rel="noreferrer">风味</a>的<a href="https://baike.baidu.com/item/%E9%A3%9F%E5%93%81/174284?fromModule=lemma_inlink" target="_blank" rel="noreferrer">食品</a>。小麦粉中<a href="https://baike.baidu.com/item/%E7%A2%B3%E6%B0%B4%E5%8C%96%E7%89%A9/12760628?fromModule=lemma_inlink" target="_blank" rel="noreferrer">碳水化物</a>含量在70%以上，主要由淀粉、纤维素和其他<a href="https://baike.baidu.com/item/%E7%B3%96%E7%B1%BB/1513051?fromModule=lemma_inlink" target="_blank" rel="noreferrer">糖类</a>组成，是人体能量的主要来源。</p><h2 id="质量指标" tabindex="-1">质量指标 <a class="header-anchor" href="#质量指标" aria-label="Permalink to “质量指标”">​</a></h2><p>小麦粉一般分为：<strong>精制粉</strong>、<strong>标准粉</strong>、<strong>普通粉</strong>三种类别。其类别划分按照现行(2023-01-01实施)国家标准文件<a href="https://openstd.samr.gov.cn/bzgk/gb/newGbInfo?hcno=7FBA509CDA87E5C9DE846BBC077430B4&amp;refer=outter" target="_blank" rel="noreferrer">GB/T 1355-2021</a>中的各种质量指标进行划分，分别为：<strong>加工精度</strong>（小麦粉中残留麸皮碎片的程度）、<strong>灰分含量</strong>(以干基计)、<strong>脂肪酸值</strong>(以湿基，KOH计)、<strong>水分含量</strong>、<strong>含砂量</strong>、<strong>磁性金属物</strong>、<strong>色泽</strong>、<strong>气味</strong>、<strong>外观形态</strong>、<strong>湿面筋含量</strong>。</p><table><thead><tr><th>质量标准</th><th>精制粉</th><th>标准粉</th><th>普通粉</th></tr></thead><tbody><tr><td>加工精度</td><td colspan="3">按标准样品或仪器测定值对照检验麸星</td></tr><tr><td>灰分含量/% </td><td>≤0.70</td><td>≤1.10</td><td>≤1.60</td></tr><tr><td>脂肪酸值/(mg/100g)</td><td colspan="3">≤80</td></tr><tr><td>水分含量/%</td><td colspan="3">≤14.5</td></tr><tr><td>含砂量/%</td><td colspan="3">≤0.02</td></tr><tr><td>磁性金属物/(g/kg)</td><td colspan="3">≤0.003</td></tr><tr><td>色泽、气味</td><td colspan="3">正常</td></tr><tr><td>外观形态</td><td colspan="3">粉状或微粒状，无结块</td></tr><tr><td>湿面筋含量/%</td><td colspan="3">≥22.0</td></tr></tbody></table>',7)])])}const b=r(n,[["render",l]]);export{g as __pageData,b as default};
